//! faberline/lumen#36: each TLS plane hot-reloads on its own.
//!
//! The serving plane (`ServingTlsConfig::reloadable`) and the peer plane
//! (`PeerTlsConfig::reloadable`) are two `peer_tls::ReloadableTls` handles over
//! two projected directories. These tests rewrite the files of one plane and
//! check that a valid rotation activates, an invalid one keeps the
//! last-known-good leaf, and neither plane changes the other.
//!
//! Every key is generated by rcgen at test time and lives in a temp dir. No
//! assertion prints key or certificate material.

use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use peer_tls::{install_default_crypto_provider, Rejection, RejectionReason};
use rcgen::{
    BasicConstraints, Certificate, CertificateParams, DnType, ExtendedKeyUsagePurpose, IsCa,
    KeyPair,
};

use crate::infrastructure::tls::{PeerTlsConfig, ServingTlsConfig};

/// A throwaway certificate authority.
struct Authority {
    cert: Certificate,
    key: KeyPair,
}

fn authority(name: &str) -> Authority {
    let mut params = CertificateParams::new(Vec::new()).unwrap();
    params.distinguished_name.push(DnType::CommonName, name);
    params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
    let key = KeyPair::generate().unwrap();
    let cert = params.self_signed(&key).unwrap();
    Authority { cert, key }
}

/// Issue a leaf for `dns` signed by `identity_ca`, with the given usages.
/// Returns `(certificate PEM, key PEM)`.
fn issue(
    identity_ca: &Authority,
    dns: &[&str],
    usages: &[ExtendedKeyUsagePurpose],
) -> (String, String) {
    let mut params =
        CertificateParams::new(dns.iter().map(|n| (*n).to_string()).collect::<Vec<_>>()).unwrap();
    params.distinguished_name.push(DnType::CommonName, dns[0]);
    params.extended_key_usages = usages.to_vec();
    let key = KeyPair::generate().unwrap();
    let cert = params
        .signed_by(&key, &identity_ca.cert, &identity_ca.key)
        .unwrap();
    (cert.pem(), key.serialize_pem())
}

/// Write `tls.crt` / `tls.key` / `ca.crt` into `dir`, the three keys a
/// projected Secret carries. A rotation is a rewrite of these same paths.
fn project(dir: &Path, cert_pem: &str, key_pem: &str, ca_pem: &str) {
    std::fs::write(dir.join("tls.crt"), cert_pem).unwrap();
    std::fs::write(dir.join("tls.key"), key_pem).unwrap();
    std::fs::write(dir.join("ca.crt"), ca_pem).unwrap();
}

/// A leaf usable on both planes: server and client auth.
fn write_leaf(dir: &Path, ca: &Authority, dns: &[&str]) {
    let (cert, key) = issue(
        ca,
        dns,
        &[
            ExtendedKeyUsagePurpose::ServerAuth,
            ExtendedKeyUsagePurpose::ClientAuth,
        ],
    );
    project(dir, &cert, &key, &ca.cert.pem());
}

fn serving_config(dir: &Path, dns: &[&str]) -> ServingTlsConfig {
    ServingTlsConfig {
        cert: dir.join("tls.crt"),
        key: dir.join("tls.key"),
        ca: dir.join("ca.crt"),
        dns_names: dns.iter().map(|n| (*n).to_string()).collect(),
    }
}

fn peer_config(dir: &Path) -> PeerTlsConfig {
    PeerTlsConfig {
        cert: dir.join("tls.crt"),
        key: dir.join("tls.key"),
        ca: dir.join("ca.crt"),
        required: true,
    }
}

fn peer_reloadable(dir: &Path) -> peer_tls::ReloadableTls {
    peer_config(dir)
        .reloadable(["localhost".to_string()], std::iter::empty::<String>())
        .unwrap()
}

// --- Peer mTLS harness, copied from `peer_mtls.rs` (its helpers are private).

/// Peer material laid out as `spec.peerTlsSecret` projects it.
struct Material {
    _dir: tempfile::TempDir,
    config: PeerTlsConfig,
}

/// `identity_ca` signs the leaf; `trust_ca` is who the holder verifies against.
fn material(identity_ca: &Authority, trust_ca: &Authority, dns: &[&str]) -> Material {
    let (cert, key) = issue(
        identity_ca,
        dns,
        &[
            ExtendedKeyUsagePurpose::ServerAuth,
            ExtendedKeyUsagePurpose::ClientAuth,
        ],
    );
    let dir = tempfile::tempdir().unwrap();
    project(dir.path(), &cert, &key, &trust_ca.cert.pem());
    Material {
        config: peer_config(dir.path()),
        _dir: dir,
    }
}

struct PeerListener {
    port: u16,
    router_reached: Arc<AtomicBool>,
    shutdown: tokio::sync::oneshot::Sender<()>,
    serve: tokio::task::JoinHandle<anyhow::Result<()>>,
}

async fn peer_listener(config: &PeerTlsConfig) -> PeerListener {
    let router_reached = Arc::new(AtomicBool::new(false));
    let flag = router_reached.clone();
    let router = axum::Router::new().route(
        "/raft/append",
        axum::routing::post(move || {
            let flag = flag.clone();
            async move {
                flag.store(true, Ordering::SeqCst);
                "appended"
            }
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let transport = config.peer_transport().unwrap();
    let (shutdown, rx) = tokio::sync::oneshot::channel();
    let serve = tokio::spawn(async move {
        transport
            .serve(listener, router, async move {
                let _ = rx.await;
            })
            .await
    });
    PeerListener {
        port,
        router_reached,
        shutdown,
        serve,
    }
}

impl PeerListener {
    fn reached(&self) -> bool {
        self.router_reached.load(Ordering::SeqCst)
    }

    async fn stop(self) {
        let _ = self.shutdown.send(());
        self.serve.await.unwrap().unwrap();
    }
}

// --- Serving plane.

#[test]
fn serving_valid_rotation_advances_generation_and_changes_the_served_leaf() {
    install_default_crypto_provider();
    let ca = authority("lumen serving test CA");
    let dir = tempfile::tempdir().unwrap();
    write_leaf(dir.path(), &ca, &["localhost"]);
    let tls = serving_config(dir.path(), &["localhost"])
        .reloadable()
        .unwrap();
    let generation = tls.generation();
    let fingerprint = tls.fingerprint();
    assert!(fingerprint.is_some(), "a leaf is active at startup");

    // Negative control: nothing was rewritten, so nothing may activate.
    assert_eq!(tls.reload().unwrap(), generation);
    assert_eq!(tls.fingerprint(), fingerprint);

    write_leaf(dir.path(), &ca, &["localhost"]);
    let rotated = tls
        .reload()
        .expect("a valid leaf from the same CA must activate");
    assert!(rotated > generation, "generation must advance on rotation");
    assert_eq!(tls.generation(), rotated);
    assert_ne!(
        tls.fingerprint(),
        fingerprint,
        "the served leaf must be the new one"
    );
}

#[test]
fn serving_invalid_replacement_keeps_the_last_known_good_leaf() {
    install_default_crypto_provider();
    let ca = authority("lumen serving test CA");
    let dir = tempfile::tempdir().unwrap();
    write_leaf(dir.path(), &ca, &["localhost"]);
    let tls = serving_config(dir.path(), &["localhost"])
        .reloadable()
        .unwrap();
    let generation = tls.generation();
    let fingerprint = tls.fingerprint();

    std::fs::write(dir.path().join("tls.crt"), "not a pem").unwrap();
    let error = tls
        .reload()
        .expect_err("garbage in tls.crt must be refused");

    assert_eq!(error.reason, RejectionReason::MalformedPem);
    assert_eq!(tls.generation(), generation, "generation is unchanged");
    assert_eq!(tls.fingerprint(), fingerprint, "the old leaf still serves");
    assert!(
        tls.server_config().is_some(),
        "last-known-good keeps a server config"
    );
    let text = error.to_string();
    assert!(
        !text.contains("PRIVATE KEY") && !text.contains("BEGIN"),
        "the rejection must not carry PEM text"
    );
    let path = dir.path().to_string_lossy();
    assert!(
        !text.contains(path.as_ref()),
        "the rejection must not carry the projection path"
    );

    // Control: valid material from the same CA passes.
    write_leaf(dir.path(), &ca, &["localhost"]);
    assert!(tls.reload().is_ok(), "valid material must activate again");
}

#[test]
fn serving_leaf_for_another_name_is_refused_at_reload() {
    install_default_crypto_provider();
    let ca = authority("lumen serving test CA");
    let dir = tempfile::tempdir().unwrap();
    write_leaf(dir.path(), &ca, &["localhost"]);
    let tls = serving_config(dir.path(), &["localhost"])
        .reloadable()
        .unwrap();
    let generation = tls.generation();
    let fingerprint = tls.fingerprint();

    // Chain-valid, in date, same CA: only the name is wrong.
    write_leaf(dir.path(), &ca, &["other.acme.svc"]);
    let error = tls
        .reload()
        .expect_err("a leaf for another Service name must be refused");

    assert_eq!(error.reason, RejectionReason::WrongIdentity);
    assert_eq!(tls.generation(), generation);
    assert_eq!(
        tls.fingerprint(),
        fingerprint,
        "the previous leaf stays active"
    );
}

// --- Peer plane.

#[tokio::test]
async fn peer_valid_rotation_keeps_mtls_working_and_changes_the_identity() {
    install_default_crypto_provider();
    let ca = authority("lumen peer test CA");
    let dir = tempfile::tempdir().unwrap();
    write_leaf(dir.path(), &ca, &["localhost"]);
    let tls = peer_reloadable(dir.path());
    let generation = tls.generation();
    let fingerprint = tls.fingerprint();

    write_leaf(dir.path(), &ca, &["localhost"]);
    tls.reload()
        .expect("a valid peer leaf from the same CA must activate");
    assert!(tls.generation() > generation, "generation must advance");
    assert_ne!(tls.fingerprint(), fingerprint, "the peer identity changed");

    // The peer listener is built over the rotated material and completes an
    // mTLS exchange with a dialer from the same trust domain.
    let server = peer_config(dir.path());
    let listener = peer_listener(&server).await;
    let dialer = material(&ca, &ca, &["localhost"]);
    let response = dialer
        .config
        .peer_transport()
        .unwrap()
        .http_client()
        .post(format!("https://localhost:{}/raft/append", listener.port))
        .send()
        .await
        .expect("a rotated peer identity must still complete the exchange");
    assert!(response.status().is_success(), "{:?}", response.status());
    assert!(
        listener.reached(),
        "the exchange must reach the Raft router"
    );
    listener.stop().await;

    // Negative control: a client certificate from an unrelated CA is still
    // refused after the rotation.
    let unrelated = authority("unrelated CA");
    let impostor = material(&unrelated, &ca, &["localhost"]);
    let refused_listener = peer_listener(&server).await;
    let error = impostor
        .config
        .peer_transport()
        .unwrap()
        .http_client()
        .post(format!(
            "https://localhost:{}/raft/append",
            refused_listener.port
        ))
        .send()
        .await
        .expect_err("a peer leaf from an unrelated CA must be refused after rotation");
    assert!(
        !refused_listener.reached(),
        "an unrelated-CA peer must not reach the router: {error}"
    );
    refused_listener.stop().await;
}

#[test]
fn peer_invalid_replacement_keeps_the_last_known_good_identity() {
    install_default_crypto_provider();
    let ca = authority("lumen peer test CA");
    let dir = tempfile::tempdir().unwrap();
    write_leaf(dir.path(), &ca, &["localhost"]);
    let tls = peer_reloadable(dir.path());
    let generation = tls.generation();
    let fingerprint = tls.fingerprint();

    std::fs::write(dir.path().join("tls.key"), "not a pem").unwrap();
    let error = tls.reload().expect_err("a garbage key must be refused");

    assert_eq!(tls.generation(), generation, "generation is unchanged");
    assert_eq!(
        tls.fingerprint(),
        fingerprint,
        "the last-known-good identity stays"
    );
    let text = error.to_string();
    assert!(
        !text.contains("PRIVATE KEY"),
        "the rejection must not carry key PEM"
    );
    let path = dir.path().to_string_lossy();
    assert!(
        !text.contains(path.as_ref()),
        "the rejection must not carry the projection path"
    );

    // Control: restore valid material and it activates again.
    write_leaf(dir.path(), &ca, &["localhost"]);
    assert!(tls.reload().is_ok(), "valid material must activate again");
}

// --- Cross-plane.

#[test]
fn rotating_one_plane_never_touches_the_other() {
    install_default_crypto_provider();
    let ca = authority("lumen plane test CA");
    let serving_dir = tempfile::tempdir().unwrap();
    let peer_dir = tempfile::tempdir().unwrap();
    write_leaf(serving_dir.path(), &ca, &["localhost"]);
    write_leaf(peer_dir.path(), &ca, &["localhost"]);
    let serving = serving_config(serving_dir.path(), &["localhost"])
        .reloadable()
        .unwrap();
    let peer = peer_reloadable(peer_dir.path());

    assert_ne!(
        serving.fingerprint(),
        peer.fingerprint(),
        "two planes hold two leaves, never one shared key"
    );

    // Rotate only the serving plane: the peer handle does not move.
    let peer_before = (peer.generation(), peer.fingerprint());
    write_leaf(serving_dir.path(), &ca, &["localhost"]);
    serving.reload().expect("serving rotation activates");
    assert_ne!(serving.fingerprint(), peer_before.1, "serving did rotate");
    assert_eq!(
        (peer.generation(), peer.fingerprint()),
        peer_before,
        "rotating serving must not change the peer plane"
    );

    // Rotate only the peer plane: the serving handle does not move.
    let serving_before = (serving.generation(), serving.fingerprint());
    write_leaf(peer_dir.path(), &ca, &["localhost"]);
    peer.reload().expect("peer rotation activates");
    assert_ne!(peer.fingerprint(), peer_before.1, "peer did rotate");
    assert_eq!(
        (serving.generation(), serving.fingerprint()),
        serving_before,
        "rotating the peer must not change the serving plane"
    );
}

#[test]
fn a_serving_leaf_is_not_accepted_as_a_peer_identity() {
    // Characterization: a leaf that carries only ServerAuth is a valid serving
    // identity but not a peer identity, which must also prove ClientAuth. The
    // shared seam refuses it at startup, so it can never be presented on the
    // peer listener.
    install_default_crypto_provider();
    let ca = authority("lumen plane test CA");
    let dir = tempfile::tempdir().unwrap();
    let (cert, key) = issue(&ca, &["localhost"], &[ExtendedKeyUsagePurpose::ServerAuth]);
    project(dir.path(), &cert, &key, &ca.cert.pem());

    let error = match peer_config(dir.path())
        .reloadable(["localhost".to_string()], std::iter::empty::<String>())
    {
        Ok(_) => panic!("a ServerAuth-only leaf must not start the peer plane"),
        Err(error) => error,
    };
    let rejection = error
        .downcast_ref::<Rejection>()
        .expect("the refusal is a typed peer_tls rejection");
    assert_eq!(rejection.reason, RejectionReason::MissingUsage);
}
